INSERT OR REPLACE INTO "IMPORT Rebates" SELECT coalesce(k0."Customer Group", error('cells name a member Customer Group does not have: ' || c."Customer Group")), coalesce(k1."Years", error('cells name a member Years does not have: ' || c."Years")), coalesce(k2."Months", error('cells name a member Months does not have: ' || c."Months")), sum(c.value::DOUBLE)
